export function WalletIcon({ name, className = "size-5" }: { name: WalletIconName; className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden
    >
      {ICONS[name]}
    </svg>
  );
}

/** Back button + centered title, like the mobile wallet screens' header. */
export function BackHeader({
  title,
  backHref,
  right,
}: {
  title: string;
  backHref: string;
  right?: ReactNode;
}) {
  return (
    <div className="flex items-center justify-between gap-3">
      <Link
        href={backHref}
        aria-label="Back"
        className="flex size-9 items-center justify-center rounded-full bg-gray-100 text-gray-600 transition hover:bg-gray-200"
      >
        <WalletIcon name="arrow-left" />
      </Link>
      <h1 className="font-display text-lg font-extrabold text-gray-900">{title}</h1>
      {right ?? <span className="size-9" />}
    </div>
  );
}